@tailwind base;
@tailwind components;
@tailwind utilities;

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@100..900&family=Space+Grotesk:wght@300..700&display=swap');

@layer base {
  * {
    @apply border-border;
  }

  body {
    @apply bg-background text-foreground font-sans;
    font-feature-settings: "rlig" 1, "calt" 1;
  }
}

@layer base {
  :root {
    /* Light mode colors */
    --background: 0 0% 100%;
    --foreground: 240 10% 3.9%;
    --card: 0 0% 100%;
    --card-foreground: 240 10% 3.9%;
    --card-border: 240 5.9% 90%;
    --popover: 0 0% 100%;
    --popover-foreground: 240 10% 3.9%;
    --popover-border: 240 5.9% 90%;
    --primary: 240 5.9% 10%;
    --primary-foreground: 0 0% 98%;
    --primary-border: hsl(240 5.9% 10%);
    --secondary: 240 4.8% 95.9%;
    --secondary-foreground: 240 5.9% 10%;
    --secondary-border: hsl(240 4.8% 85.9%);
    --muted: 240 4.8% 95.9%;
    --muted-foreground: 240 3.8% 46.1%;
    --muted-border: hsl(240 4.8% 85.9%);
    --accent: 240 4.8% 95.9%;
    --accent-foreground: 240 5.9% 10%;
    --accent-border: hsl(240 4.8% 85.9%);
    --destructive: 0 84.2% 60.2%;
    --destructive-foreground: 0 0% 98%;
    --destructive-border: hsl(0 84.2% 60.2%);
    --border: 240 5.9% 90%;
    --input: 240 5.9% 90%;
    --ring: 240 5% 64.9%;
    --chart-1: 12 76% 61%;
    --chart-2: 173 58% 39%;
    --chart-3: 197 37% 24%;
    --chart-4: 43 74% 66%;
    --chart-5: 27 87% 67%;
    --sidebar: var(--background);
    --sidebar-foreground: var(--foreground);
    --sidebar-border: var(--border);
    --sidebar-ring: var(--ring);
    --sidebar-primary: var(--primary);
    --sidebar-primary-foreground: var(--primary-foreground);
    --sidebar-primary-border: var(--primary-border);
    --sidebar-accent: var(--accent);
    --sidebar-accent-foreground: var(--accent-foreground);
    --sidebar-accent-border: var(--accent-border);

    /* Custom elevation and hover variables */
    --elevation-intensity: 8; /* In terms of percentages */
    --opaque-button-border-intensity: -8; /* In terms of percentages */
    --button-outline: 240 5.9% 80%;
  }

  .dark {
    /* Dark mode colors - Fleet Sentinel luxury theme */
    --background: 220 30% 8%;
    --foreground: 210 15% 92%;
    --card: 220 25% 12%;
    --card-foreground: 210 15% 90%;
    --card-border: 220 20% 18%;
    --popover: 220 25% 12%;
    --popover-foreground: 210 15% 90%;
    --popover-border: 220 20% 18%;
    --primary: 217 91% 60%;
    --primary-foreground: 220 30% 8%;
    --primary-border: hsl(217 91% 60%);
    --secondary: 220 20% 16%;
    --secondary-foreground: 210 15% 85%;
    --secondary-border: hsl(220 15% 24%);
    --muted: 220 20% 14%;
    --muted-foreground: 220 8% 60%;
    --muted-border: hsl(220 15% 20%);
    --accent: 220 20% 16%;
    --accent-foreground: 210 15% 85%;
    --accent-border: hsl(220 15% 24%);
    --destructive: 0 75% 65%;
    --destructive-foreground: 0 0% 95%;
    --destructive-border: hsl(0 75% 65%);
    --border: 220 20% 18%;
    --input: 220 20% 18%;
    --ring: 217 91% 60%;
    --chart-1: 217 91% 60%;
    --chart-2: 160 84% 39%;
    --chart-3: 30 80% 55%;
    --chart-4: 280 65% 60%;
    --chart-5: 340 75% 55%;
    --sidebar: 220 25% 10%;
    --sidebar-foreground: 210 15% 88%;
    --sidebar-border: 220 20% 16%;
    --sidebar-ring: 217 91% 60%;
    --sidebar-primary: 217 91% 60%;
    --sidebar-primary-foreground: 220 30% 8%;
    --sidebar-primary-border: hsl(217 91% 60%);
    --sidebar-accent: 220 20% 18%;
    --sidebar-accent-foreground: 210 15% 85%;
    --sidebar-accent-border: hsl(220 15% 26%);

    /* Dark mode custom variables */
    --elevation-intensity: 12;
    --opaque-button-border-intensity: 12;
    --button-outline: 220 20% 25%;
  }
}

/* Custom utility classes for luxury interactions */
@layer utilities {
  .hover-elevate {
    @apply transition-all duration-200 ease-out;
  }

  .hover-elevate:hover {
    @apply bg-opacity-[calc(100%+var(--elevation-intensity))] shadow-md transform scale-[1.02];
  }

  .active-elevate-2 {
    @apply transition-all duration-100 ease-out;
  }

  .active-elevate-2:active {
    @apply bg-opacity-[calc(100%+calc(var(--elevation-intensity)*2))] shadow-lg transform scale-[0.98];
  }

  .no-default-hover-elevate:hover {
    @apply bg-opacity-100 shadow-none transform-none scale-100;
  }

  .no-default-active-elevate:active {
    @apply bg-opacity-100 shadow-none transform-none scale-100;
  }

  .toggle-elevate {
    @apply transition-all duration-200 ease-out;
  }

  .toggle-elevated {
    @apply bg-opacity-[calc(100%+var(--elevation-intensity))] shadow-md;
  }
}

/* Scrollbar styling for luxury feel */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  @apply bg-background;
}

::-webkit-scrollbar-thumb {
  @apply bg-border rounded-full;
}

::-webkit-scrollbar-thumb:hover {
  @apply bg-muted-foreground;
}

/* Focus states for accessibility */
.focus-visible:focus-visible {
  @apply outline-none ring-2 ring-primary ring-offset-2 ring-offset-background;
}

/* Animation classes */
.fade-in {
  animation: fade-in 0.5s ease-out;
}

.slide-in-right {
  animation: slide-in-right 0.3s ease-out;
}

.pulse-glow {
  animation: pulse-glow 2s ease-in-out infinite;
}

.liquid-flow {
  animation: liquid-flow 20s ease-in-out infinite;
}

