];

const reportTemplates = {
  "fuel-cost": {
    title: "Fleet Fuel & Cost Analysis",
    description: "Comprehensive financial overview of all fuel-related activities to control costs",
    category: "Financial"
  },
  "utilization": {
    title: "Asset Utilization & Performance", 
    description: "Analyzes how effectively vehicles are being used to maximize operational productivity",
    category: "Operations"
  },
  "compliance": {
    title: "Safety & Compliance",
    description: "Consolidates all safety and policy-related events for auditing and risk management",
    category: "Safety"
  }
};

// Helper function to get status badge styling and icon
const getStatusBadge = (status: string) => {
  switch (status) {
    case "Complete":
      return {
        icon: CheckCircle2,
        variant: "default" as const,
        className: "bg-primary/10 text-primary border-primary/20 hover:bg-primary/15"
      };
    case "Processing":
      return {
        icon: Clock,
        variant: "secondary" as const,
        className: "bg-accent/10 text-accent-foreground border-accent/20 hover:bg-accent/15"
      };
    case "Failed":
      return {
