};

export function ReportsPage() {
  const { toast } = useToast();

  const [selectedAssetGroup, setSelectedAssetGroup] = useState("");
  const [dateFrom, setDateFrom] = useState("");
  const [dateTo, setDateTo] = useState("");
  const [isGenerating, setIsGenerating] = useState(false);

  // Modal states
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedTemplate, setSelectedTemplate] = useState<string | null>(null);

  const handleTemplateSelect = (templateType: string) => {
    setSelectedTemplate(templateType);
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setSelectedTemplate(null);
    // Reset form when modal closes
    setSelectedAssetGroup("");
    setDateFrom("");
    setDateTo("");
  };

  const handleGenerateFromModal = async () => {
    if (!selectedAssetGroup || !dateFrom || !dateTo || !selectedTemplate) {
      toast({
        title: "Missing Information",
        description: "Please fill in all required fields before generating the report.",
        variant: "destructive"
      });
      return;
    }

    setIsGenerating(true);

    const template = reportTemplates[selectedTemplate as keyof typeof reportTemplates];

    // Show immediate feedback
    toast({
      title: "Report Generation Started",
      description: `${template.title} is being generated and will appear in your queue shortly.`,
    });

    // Simulate report generation
    setTimeout(() => {
      setIsGenerating(false);
      setIsModalOpen(false);

      toast({
        title: "Report Generated Successfully",
        description: `${template.title} for ${assetGroups.find(g => g.id === selectedAssetGroup)?.label} (${dateFrom} to ${dateTo})`,
      });

      // Reset form
      setSelectedAssetGroup("");
      setDateFrom("");
      setDateTo("");
      setSelectedTemplate(null);
    }, 3000);
  };

  const handleDownloadReport = (reportId: number, reportName: string, reportType: string) => {
    // Generate mock CSV data based on report type
    let csvData = "";

    if (reportType === "Financial") {
      csvData = `Report: ${reportName}\nGenerated: ${new Date().toISOString()}\n\nAsset,Fuel Cost,Distance (km),Efficiency (L/100km)\nSEM-123,12500,450,9.2\nSEM-124,11800,520,8.8\nSEM-125,13200,380,11.1\n`;
    } else if (reportType === "Utilization") {
      csvData = `Report: ${reportName}\nGenerated: ${new Date().toISOString()}\n\nAsset,Utilization %,Maintenance Status,Compliance %\nSEM-123,87,Up to Date,94\nSEM-124,92,Due Soon,96\nSEM-125,79,Overdue,89\n`;
    } else {
      csvData = `Report: ${reportName}\nGenerated: ${new Date().toISOString()}\n\nAsset,Status,Event Count,Last Event\nSEM-123,Normal,0,N/A\nSEM-124,Alert,2,2024-09-20\nSEM-125,Normal,1,2024-09-18\n`;
    }

    // Create and trigger download
    const blob = new Blob([csvData], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${reportName.replace(/\s+/g, '_')}.csv`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    window.URL.revokeObjectURL(url);

    toast({
      title: "Download started",
      description: `${reportName} has been downloaded as CSV file.`,
    });
  };

  return (
    <div className="space-y-8">
      {/* Page Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-foreground mb-2 flex items-center gap-3">
            <FileText className="w-8 h-8 text-primary" />
            Reports Center
          </h1>
          <p className="text-muted-foreground">Generate professional, branded reports for stakeholders and compliance</p>
        </div>
      </div>

      {/* Report Template Library */}
      <GlassCard className="p-6">
        <h2 className="text-2xl font-bold text-foreground mb-2">Report Template Library</h2>
        <p className="text-muted-foreground mb-8">Choose from our curated report templates designed for fleet intelligence and decision-making.</p>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {/* Fleet Fuel & Cost Analysis Report */}
          <GlassCard className="p-6 hover-elevate motion-premium cursor-pointer border border-border/30" data-testid="template-fuel-cost">
            <div className="flex items-start justify-between mb-4">
              <div className="p-3 rounded-lg bg-primary/10 border border-primary/20">
                <FileText className="w-6 h-6 text-primary" />
              </div>
              <div className="text-xs text-muted-foreground bg-card/20 px-2 py-1 rounded-full border border-border/20">
                Financial
              </div>
            </div>

            <h3 className="text-lg font-semibold text-foreground mb-2">Fleet Fuel & Cost Analysis</h3>
            <p className="text-sm text-muted-foreground mb-4 line-clamp-2">
              Provides a comprehensive financial overview of all fuel-related activities to control costs.
            </p>

            <div className="space-y-2 mb-6">
              <div className="text-xs text-muted-foreground font-medium">Key Metrics Include:</div>
              <div className="flex flex-wrap gap-1">
                <span className="text-xs bg-primary/10 text-primary px-2 py-1 rounded-full">Total Fuel Cost</span>
                <span className="text-xs bg-primary/10 text-primary px-2 py-1 rounded-full">Volume Consumed</span>
                <span className="text-xs bg-primary/10 text-primary px-2 py-1 rounded-full">Fleet Efficiency</span>
                <span className="text-xs bg-primary/10 text-primary px-2 py-1 rounded-full">Theft Incidents</span>
              </div>
            </div>

            <Button 
              className="w-full" 
              onClick={() => handleTemplateSelect("fuel-cost")}
              data-testid="button-generate-fuel-cost"
            >
              Generate Report
            </Button>
          </GlassCard>

          {/* Asset Utilization & Performance Report */}
          <GlassCard className="p-6 hover-elevate motion-premium cursor-pointer border border-border/30" data-testid="template-utilization">
            <div className="flex items-start justify-between mb-4">
              <div className="p-3 rounded-lg bg-primary/10 border border-primary/20">
                <FileText className="w-6 h-6 text-primary" />
              </div>
              <div className="text-xs text-muted-foreground bg-card/20 px-2 py-1 rounded-full border border-border/20">
                Operations
