              <div className="flex flex-wrap gap-1">
                <span className="text-xs bg-primary/10 text-primary px-2 py-1 rounded-full">Distance Traveled</span>
                <span className="text-xs bg-primary/10 text-primary px-2 py-1 rounded-full">Engine Hours</span>
                <span className="text-xs bg-primary/10 text-primary px-2 py-1 rounded-full">Idle vs Drive Time</span>
                <span className="text-xs bg-primary/10 text-primary px-2 py-1 rounded-full">Trip Analytics</span>
              </div>
            </div>

            <Button 
              className="w-full" 
              onClick={() => handleTemplateSelect("utilization")}
              data-testid="button-generate-utilization"
            >
              Generate Report
            </Button>
          </GlassCard>

          {/* Safety & Compliance Report */}
          <GlassCard className="p-6 hover-elevate motion-premium cursor-pointer border border-border/30" data-testid="template-compliance">
            <div className="flex items-start justify-between mb-4">
              <div className="p-3 rounded-lg bg-accent/10 border border-accent/20">
                <FileText className="w-6 h-6 text-accent-foreground" />
              </div>
              <div className="text-xs text-muted-foreground bg-card/20 px-2 py-1 rounded-full border border-border/20">
                Safety
              </div>
            </div>

            <h3 className="text-lg font-semibold text-foreground mb-2">Safety & Compliance</h3>
            <p className="text-sm text-muted-foreground mb-4 line-clamp-2">
              Consolidates all safety and policy-related events into a single document for auditing and risk management.
            </p>

            <div className="space-y-2 mb-6">
              <div className="text-xs text-muted-foreground font-medium">Key Metrics Include:</div>
              <div className="flex flex-wrap gap-1">
                <span className="text-xs bg-accent/10 text-accent-foreground px-2 py-1 rounded-full">Maintenance Score</span>
                <span className="text-xs bg-accent/10 text-accent-foreground px-2 py-1 rounded-full">Geofence Compliance</span>
                <span className="text-xs bg-accent/10 text-accent-foreground px-2 py-1 rounded-full">Safety Incidents</span>
                <span className="text-xs bg-accent/10 text-accent-foreground px-2 py-1 rounded-full">Critical Alerts</span>
              </div>
            </div>

            <Button 
              className="w-full" 
              onClick={() => handleTemplateSelect("compliance")}
              data-testid="button-generate-compliance"
            >
              Generate Report
            </Button>
          </GlassCard>
        </div>
      </GlassCard>

      {/* Report History & Queue */}
      <GlassCard className="p-6">
        <h3 className="text-lg font-bold text-foreground mb-4 flex items-center gap-2">
          <FileText className="w-4 h-4 text-primary" />
          Report History & Queue
        </h3>
        <p className="text-sm text-muted-foreground mb-6">Monitor report generation status and access completed reports</p>

        <div className="space-y-4">
          {recentReports.map((report) => {
            const statusBadge = getStatusBadge(report.status);
            const StatusIcon = statusBadge.icon;

            const statusGlow = report.status === "Complete" ? "good" : 
                             report.status === "Processing" ? "neutral" : 
                             report.status === "Failed" ? "danger" : "neutral";

            return (
              <GlassCard key={report.id} className="p-4" statusGlow={statusGlow} data-testid={`report-item-${report.id}`}>
                <div className="flex items-start justify-between mb-3">
                  <div className="flex items-start gap-3 flex-1">
                    <div className="flex items-center justify-center w-10 h-10 rounded-xl bg-primary/10 flex-shrink-0">
                      <FileText className="w-5 h-5 text-primary" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-1">
                        <div className="font-semibold text-foreground truncate" data-testid={`text-report-name-${report.id}`}>
                          {report.name}
                        </div>
                        <Badge 
                          className={`${statusBadge.className} flex items-center gap-1 text-xs font-medium`}
                          data-testid={`badge-status-${report.id}`}
                        >
                          <StatusIcon className="w-3 h-3" />
                          {report.status}
                        </Badge>
                      </div>
                      <div className="text-sm text-muted-foreground mb-2">
                        <span className="bg-accent/20 text-accent-foreground px-2 py-0.5 rounded-full text-xs font-medium mr-2">
                          {report.type}
                        </span>
                        {report.generated} at {report.generatedTime}
                      </div>

                      {/* Progress Bar for Processing */}
                      {report.status === "Processing" && (
                        <div className="mb-2">
                          <div className="flex items-center justify-between text-xs mb-1">
                            <span className="text-muted-foreground">Generation Progress</span>
                            <span className="text-accent-foreground font-medium">{report.progress}%</span>
                          </div>
                          <Progress 
                            value={report.progress} 
                            className="h-2"
                            data-testid={`progress-${report.id}`}
                          />
                          {report.estimatedTime && (
                            <div className="text-xs text-accent-foreground mt-1 flex items-center gap-1">
                              <Clock className="w-3 h-3" />
                              {report.estimatedTime}
                            </div>
                          )}
                        </div>
                      )}

                      {/* Error Message for Failed */}
                      {report.status === "Failed" && report.error && (
                        <div className="mb-2 p-2 rounded-lg bg-destructive/10 border border-destructive/20">
                          <div className="text-xs text-destructive flex items-center gap-1">
                            <AlertCircle className="w-3 h-3" />
                            {report.error}
                          </div>
                        </div>
                      )}

                      {/* File Size */}
                      <div className="text-xs text-muted-foreground">
                        File size: {report.size}
                      </div>
                    </div>
                  </div>

                  {/* Action Buttons */}
                  <div className="flex items-center gap-2 ml-3">
                    {report.status === "Complete" && (
                      <Button
                        size="sm"
                        onClick={() => handleDownloadReport(report.id, report.name, report.type)}
                        data-testid={`button-download-${report.id}`}
                      >
                        <Download className="w-3 h-3 mr-1" />
                        Download
                      </Button>
                    )}
                    {report.status === "Processing" && (
                      <Button
                        size="sm"
                        variant="outline"
                        disabled
                        data-testid={`button-processing-${report.id}`}
                      >
                        <Clock className="w-3 h-3 mr-1 animate-spin" />
                        Processing
                      </Button>
                    )}
                    {report.status === "Failed" && (
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() => handleTemplateSelect(report.templateId)} // Retry with correct template
                        data-testid={`button-retry-${report.id}`}
                      >
                        <AlertCircle className="w-3 h-3 mr-1" />
                        Retry
                      </Button>
                    )}
                  </div>
                </div>
              </GlassCard>
            );
          })}
        </div>
      </GlassCard>

      {/* Smart Generation Modal */}
      <Dialog open={isModalOpen} onOpenChange={handleCloseModal}>
        <DialogContent className="sm:max-w-md backdrop-blur-xl bg-card/95 border border-border/30">
          <DialogHeader className="space-y-3">
            <DialogTitle className="flex items-center gap-2 text-xl font-bold text-foreground">
              <Lightbulb className="w-5 h-5 text-primary" />
