import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Moon, Sun, Shield } from "lucide-react";
import { useTheme } from "./ThemeProvider";
import { FilterControls } from "./FilterControls";

interface HeaderProps {
  onRefresh: () => void;
}

export function Header({ onRefresh }: HeaderProps) {
  const { theme, toggleTheme } = useTheme();
  const [currentDateTime, setCurrentDateTime] = useState("");

  const updateDateTime = () => {
    const now = new Date();
    const dateStr = now.toLocaleDateString('en-GB', { 
      day: '2-digit', 
      month: 'short', 
      year: 'numeric' 
    });
    const timeStr = now.toLocaleTimeString('en-US', { 
      hour12: false, 
      hour: '2-digit', 
      minute: '2-digit',
      second: '2-digit'
    });
    setCurrentDateTime(`${dateStr} | ${timeStr} EAT`);
  };

  useEffect(() => {
    updateDateTime();
    const interval = setInterval(updateDateTime, 1000);
    return () => clearInterval(interval);
  }, []);

  return (
    <header className="sticky top-0 z-20 bg-background/60 backdrop-blur-xl border-b border-border/20">
      <div className="max-w-[1400px] mx-auto px-4 py-3">
        <div className="flex items-center justify-between gap-4">

          {/* Left side - Logo and Filters */}
          <div className="flex items-center gap-6">
            <div className="flex items-center gap-3">
              <div className="w-8 h-8 bg-primary rounded-lg flex items-center justify-center">
                <Shield className="h-5 w-5 text-primary-foreground" />
              </div>
              <div>
                <h1 className="text-lg font-bold text-foreground">Fleet Sentinel</h1>
                <p className="text-xs text-muted-foreground">Fleet Management System</p>
              </div>
            </div>

            {/* Global Filter Controls */}
            <FilterControls />
          </div>

          {/* Right side - Controls */}
          <div className="flex items-center gap-3">
            {/* Theme toggle */}
            <Button 
              variant="outline" 
              size="sm"
              onClick={toggleTheme}
              className="hover-elevate bg-card/40 backdrop-blur-sm border-border/30"
              data-testid="button-theme-toggle"
            >
              {theme === "dark" ? <Sun className="w-4 h-4" /> : <Moon className="w-4 h-4" />}
              <span className="ml-2 text-xs hidden sm:inline">Theme</span>
            </Button>

            {/* Current Date and Time */}
            <div className="text-right text-xs font-mono hidden md:block">
              <div className="text-foreground font-medium">{currentDateTime}</div>
            </div>
          </div>
        </div>
      </div>
    </header>
  );
}

